files.content:
:root {
  --bg: #1e1e2f;
  --card: #2b2b44;
  --accent: #f5c542;
  --accent-dark: #d4a72c;
  --text: #f0f0f5;
  --muted: #a0a0b8;
  --border: #3e3e5c;
  --focus: #7fd1ff;
  --radius: 10px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255,255,255,0.03) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(255,255,255,0.03) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(255,255,255,0.03) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(255,255,255,0.03) 75%);
  background-size: 24px 24px;
  background-position: 0 0, 0 12px, 12px -12px, -12px 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 3px solid var(--border);
  border-radius: var(--radius);
  padding: 28px 24px;
  box-shadow: 6px 6px 0 rgba(0, 0, 0, 0.35);
}

h1 {
  margin: 0 0 8px;
  font-size: 1.5rem;
  line-height: 1.2;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0 0 24px;
  color: var(--muted);
  font-size: 1rem;
}

.field {
  margin-bottom: 18px;
}

label {
  display: block;
  margin-bottom: 6px;
  font-weight: 600;
  font-size: 1rem;
}

input[type="number"] {
  width: 100%;
  padding: 12px 14px;
  font-size: 1.125rem;
  font-family: inherit;
  color: var(--text);
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 8px;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input[type="number"]:hover {
  border-color: var(--accent-dark);
}

input[type="number"]:focus {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(127, 209, 255, 0.35);
}

.results {
  margin: 24px 0;
  padding: 16px;
  background: var(--bg);
  border: 2px dashed var(--border);
  border-radius: 8px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 6px 0;
}

.result-row + .result-row {
  border-top: 1px solid var(--border);
  margin-top: 6px;
  padding-top: 12px;
}

.result-label {
  color: var(--muted);
  font-size: 1rem;
}

.result-value {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.actions {
  display: flex;
  justify-content: flex-end;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  padding: 12px 24px;
  border-radius: 8px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s, box-shadow 0.15s;
}

.btn-reset {
  background: var(--accent);
  color: #1e1e2f;
  border-color: var(--accent-dark);
  box-shadow: 0 3px 0 var(--accent-dark);
}

.btn-reset:hover {
  background: #ffd95e;
}

.btn-reset:active {
  transform: translateY(2px);
  box-shadow: 0 1px 0 var(--accent-dark);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

@media (max-width: 400px) {
  .card {
    padding: 20px 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .result-value {
    font-size: 1.2rem;
  }
}

(function () {
  'use strict';

  var form = document.getElementById('fuel-form');
  var distanceInput = document.getElementById('distance');
  var consumptionInput = document.getElementById('consumption');
  var priceInput = document.getElementById('price');
  var litresOutput = document.getElementById('litres');
  var costOutput = document.getElementById('cost');
  var resetButton = document.getElementById('reset');

  var DEFAULTS = {
    distance: '100',
    consumption: '8',
    price: '1.75'
  };

  function parseValue(input) {
    var value = parseFloat(input.value);
    return isFinite(value) && value >= 0 ? value : 0;
  }

  function calculate() {
    var distance = parseValue(distanceInput);
    var consumption = parseValue(consumptionInput);
    var price = parseValue(priceInput);

    var litres = (distance * consumption) / 100;
    var cost = litres * price;

    litresOutput.textContent = litres.toFixed(2);
    costOutput.textContent = '\u20AC' + cost.toFixed(2);
  }

  function reset() {
    distanceInput.value = DEFAULTS.distance;
    consumptionInput.value = DEFAULTS.consumption;
    priceInput.value = DEFAULTS.price;
    calculate();
    distanceInput.focus();
  }

  form.addEventListener('input', calculate);
  form.addEventListener('submit', function (event) {
    event.preventDefault();
    calculate();
  });
  resetButton.addEventListener('click', reset);

  calculate();
})();
